# typed: strict
# frozen_string_literal: true

return unless defined?(ActiveRecord::Base)

require 'tapioca/dsl/compilers/active_record_relations'

module Tapioca
  module Dsl
    module Compilers
      # Replaces the `delete_all` and `destroy_all` signatures generated by the ActiveRecordRelations compiler,
      # since SoftDeletable extends them with deletion options (e.g. `permanent:`) for every relation.
      # Compilers decorate a constant in order of their names, so this runs after ActiveRecordRelations.
      #
      #: [ConstantType = singleton(::ActiveRecord::Base)]
      class SoftDeletableRelations < Compiler
        include Helpers::ActiveRecordConstantsHelper

        # @override
        #: -> void
        def decorate
          return unless compiler_enabled?('ActiveRecordRelations')

          root.create_path(constant) do |model|
            model.create_module(CommonRelationMethodsModuleName) do |mod|
              replace_method(mod, 'delete_all', parameters: deletion_parameters, return_type: 'Integer')
              replace_method(mod, 'destroy_all', parameters: deletion_parameters, return_type: "T::Array[#{constant_name}]")
            end

            model.create_class(AssociationsCollectionProxyClassName) do |klass|
              dependent = create_opt_param('dependent', type: 'T.nilable(Symbol)', default: 'nil')
              replace_method(klass, 'delete_all', parameters: [dependent, *deletion_parameters], return_type: 'Integer')
            end
          end
        end

        class << self
          # @override
          #: -> Enumerable[Module[top]]
          def gather_constants
            ActiveRecordRelations.gather_constants
          end
        end

      private

        #: (RBI::Scope scope, String name, parameters: Array[RBI::TypedParam], return_type: String) -> void
        def replace_method(scope, name, parameters:, return_type:)
          scope.nodes.grep(RBI::Method).select { |method| method.name == name }.each(&:detach)
          scope.create_method(name, parameters:, return_type:)
        end

        #: -> Array[RBI::TypedParam]
        def deletion_parameters
          [
            create_kw_opt_param('deleted_in', type: 'String', default: 'SecureRandom.uuid'),
            create_kw_opt_param('deleted_by', type: 'T.nilable(::ActiveRecord::Base)', default: 'nil'),
            create_kw_opt_param('permanent', type: 'T::Boolean', default: 'false'),
          ]
        end

        #: -> String
        def constant_name
          T.must(qualified_name_of(constant))
        end
      end
    end
  end
end
